<script setup lang="ts">
import { onLoad } from '@dcloudio/uni-app';import { computed,ref } from 'vue';import { api } from '../../services/api';
const id=ref('');const task=ref<any>(null);const records=ref<any>({items:[],summary:{counts:{}}});const pendingIds=computed(()=>records.value.items.filter((r:any)=>['PENDING','RETURNED'].includes(r.recordStatus)).map((r:any)=>r.assignee.id));
async function load(){try{[task.value,records.value]=await Promise.all([api(`/tasks/${id.value}`),api(`/tasks/${id.value}/records?pageSize=100`)]);}catch(e:any){uni.showToast({title:e.message,icon:'none'});}}
async function review(record:any,action:'APPROVE'|'RETURN'){const latest=record.submissions.at(-1);if(!latest)return;let comment=action==='APPROVE'?'审核通过':'';if(action==='RETURN'){const result:any=await new Promise(r=>uni.showModal({title:'退回补充',editable:true,placeholderText:'请输入退回意见',success:r}));if(!result.confirm)return;comment=result.content;if(!comment)return uni.showToast({title:'退回意见必填',icon:'none'});}try{await api(`/tasks/${id.value}/records/${record.id}/review`,'POST',{submissionId:latest.id,action,comment});uni.showToast({title:action==='APPROVE'?'已通过':'已退回'});await load();}catch(e:any){uni.showToast({title:e.message,icon:'none'});}}
async function remind(){try{await api(`/tasks/${id.value}/reminders`,'POST',{targetUserIds:pendingIds.value,channels:['IN_APP'],note:'移动管理端人工催办'});uni.showToast({title:'催办已发送'});}catch(e:any){uni.showToast({title:e.message,icon:'none'});}}
onLoad(q=>{id.value=String(q?.id??'');load();});
</script>
<template><view class="page"><view v-if="task" class="card"><text class="title">{{task.title}}</text><text class="muted">{{task.status}} · {{task.completionMode}}</text><view class="metrics"><view><b>{{records.summary.total||0}}</b><text>负责人</text></view><view><b>{{(records.summary.counts?.APPROVED||0)+(records.summary.counts?.COMPLETED||0)}}</b><text>已完成</text></view><view><b class="danger">{{pendingIds.length}}</b><text>待完成</text></view></view><button v-if="pendingIds.length" class="primary-btn" @tap="remind">催办待完成人员</button></view><text class="section-title">执行明细</text><view v-for="r in records.items" :key="r.id" class="card"><view class="row"><view><text class="name">{{r.assignee.name}}</text><text class="muted">{{r.assignee.employeeNo}}</text></view><text :class="r.derivedStatus?.startsWith('OVERDUE')?'danger':'status'">{{r.derivedStatus}}</text></view><view v-if="r.recordStatus==='SUBMITTED'" class="review"><text class="feedback">{{r.submissions.at(-1)?.feedback||'无文字反馈'}}</text><view class="review-buttons"><button class="secondary-btn" @tap="review(r,'RETURN')">退回</button><button class="primary-btn" @tap="review(r,'APPROVE')">通过</button></view></view></view></view></template>
<style scoped>.title,.muted,.name{display:block}.title{margin-bottom:10rpx;font-size:34rpx;font-weight:800}.metrics{display:grid;grid-template-columns:repeat(3,1fr);margin:28rpx 0}.metrics view{text-align:center}.metrics b,.metrics text{display:block}.metrics b{color:#007f95;font-size:38rpx}.metrics text{color:#71868a;font-size:22rpx}.row{display:flex;justify-content:space-between}.name{font-weight:700}.status{color:#2c746e}.review{margin-top:22rpx;padding-top:20rpx;border-top:1px solid #edf1f1}.feedback{display:block;margin-bottom:18rpx}.review-buttons{display:grid;grid-template-columns:1fr 1fr;gap:12rpx}.review-buttons button{font-size:24rpx}</style>
